"""Turn the effective configuration + theme into concrete config files.

Two kinds of output:

* Generated files in ~/.local/state/surfd/generated/ (Sway, Waybar,
  session environment, greeter style). Always overwritten.
* Managed files in the standard places apps look for them (GTK, foot,
  fuzzel, mako, swaylock, qt6ct). They start with a "Managed by surfctl"
  marker. Delete the marker line and surfctl leaves that file alone —
  that is how you take over one app's config by hand.
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass
from functools import cached_property
from pathlib import Path
from typing import Any

from . import color, config, dynwall, keys, paths, themes
from .themes import Palette, Theme

MARKER = "Managed by surfctl"
LIBEXEC = Path(os.environ.get("SURFD_LIBEXEC", "/usr/libexec/surfd"))


def _header(comment: str, what: str) -> str:
    return (f"{comment} {MARKER} from ~/.config/surfd/surfd.toml — {what}.\n"
            f"{comment} Change settings with `surfctl` or Surf Settings. Delete this line to\n"
            f"{comment} take this file over by hand; surfctl will then leave it alone.\n")


@dataclass
class Context:
    cfg: dict[str, Any]
    theme: Theme
    pal: Palette
    gen: Path

    def c(self, dotted: str) -> Any:
        return config.get(self.cfg, dotted)

    @property
    def custom_wallpaper(self) -> Path | None:
        """The user's own image (wallpaper.path), when set and present."""
        custom = self.c("wallpaper.path") or ""
        if custom:
            p = Path(os.path.expanduser(custom))
            if p.is_file():
                return p
        return None

    @cached_property
    def dynamic(self) -> tuple[dynwall.DynSet, Path] | None:
        """The dynamic wallpaper set and frame selected right now; None when the user's own image wins or none is set.

        Evaluated once per Context, so every file generated in one run shows the same frame.
        """
        if self.custom_wallpaper is not None:
            return None
        return dynwall.current(self.c, self.pal.variant, dynwall.now())

    @property
    def dynamic_follows_clock(self) -> bool:
        """True when a helper must keep changing the wallpaper as the day goes by."""
        return self.dynamic is not None and (self.c("wallpaper.sync") or "auto") == "auto"

    @property
    def wallpaper(self) -> Path | None:
        """The image to show: the user's own, else the dynamic frame, else the theme's."""
        if (custom := self.custom_wallpaper) is not None:
            return custom
        if self.dynamic is not None:
            return self.dynamic[1]
        return self.theme.wallpaper(self.pal.variant)

    @property
    def floating_mode(self) -> bool:
        return self.c("layout.mode") == "floating"


def build_context(cfg: dict[str, Any] | None = None) -> Context:
    cfg = cfg if cfg is not None else config.load()
    theme, pal = themes.resolve(cfg)
    return Context(cfg=cfg, theme=theme, pal=pal, gen=paths.generated_dir())


# ===================================================================== sway ==

def accent_fill(p: Palette, lighten: float = 0.0) -> str:
    """CSS background-image for surfaces filled with the accent: a teal-to-blue gradient when the
    theme defines accent2, otherwise `none` (the solid accent colour underneath shows)."""
    if p.accent2 == p.accent:
        return "none"
    a, b = (color.mix(c, "#ffffff", lighten) if lighten else c for c in (p.accent, p.accent2))
    return f"linear-gradient(to right, {a}, {b})"


def sway(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    border = int(c("layout.border_width"))
    titlebars = ctx.floating_mode or bool(c("layout.titlebars"))
    out: list[str] = [
        "# Generated by surfctl from ~/.config/surfd/surfd.toml — do not edit.",
        "# Raw Sway additions: put *.conf files in ~/.config/surfd/sway.d/",
        "",
        f"set $mod {keys.MODIFIERS[c('keys.modifier').lower()]}",
        f"font pango:{c('fonts.ui')} {max(int(c('fonts.size')) - 1, 6)}",
        "xwayland enable",
        f"focus_follows_mouse {'yes' if c('layout.focus_follows_mouse') else 'no'}",
        "mouse_warping output",
        "floating_modifier $mod normal",
        "tiling_drag enable",
        f"default_border {'normal' if titlebars else 'pixel'} {border}",
        f"default_floating_border normal {border}",
        "titlebar_padding 10 5",
        f"gaps inner {int(c('layout.gaps_inner'))}",
        f"gaps outer {int(c('layout.gaps_outer'))}",
        f"smart_gaps {'on' if c('layout.smart_gaps') else 'off'}",
        f"hide_edge_borders {'smart' if c('layout.smart_borders') else 'none'}",
        f"workspace_auto_back_and_forth {'yes' if c('layout.workspace_back_and_forth') else 'no'}",
        "focus_on_window_activation smart",
        "",
        "# colours: border background text indicator child_border",
        f"client.focused          {p.accent} {p.accent} {p.accent_text} {p.accent} {p.accent}",
        f"client.focused_inactive {p.surface_alt} {p.surface_alt} {p.text} {p.border} {p.border}",
        f"client.unfocused        {p.surface} {p.surface} {p.text_muted} {p.border} {p.border}",
        f"client.urgent           {p.urgent} {p.urgent} {color.readable_on(p.urgent)} {p.urgent} {p.urgent}",
        f"client.placeholder      {p.background} {p.background} {p.text} {p.background} {p.background}",
        f"client.background       {p.background}",
        "",
    ]

    wp = ctx.wallpaper
    if wp is not None:
        out.append(f'output * bg "{wp}" {c("wallpaper.mode")} {p.background}')
    else:
        out.append(f"output * bg {p.background} solid_color")
    scale = float(c("display.scale"))
    if scale > 0:
        out.append(f"output * scale {scale:g}")
    if c("display.adaptive_sync"):
        out.append("output * adaptive_sync on")
    out.append(f"seat seat0 xcursor_theme {ctx.theme.cursor_theme} {ctx.theme.cursor_size}")
    if c("input.hide_cursor_typing"):
        out.append("seat * hide_cursor when-typing enable")
    if int(c("input.hide_cursor_after")) > 0:
        out.append(f"seat * hide_cursor {int(c('input.hide_cursor_after')) * 1000}")

    accel = float(c("input.pointer_accel"))
    kb = [f'    xkb_layout "{c("input.keyboard_layout")}"']
    if c("input.keyboard_variant"):
        kb.append(f'    xkb_variant "{c("input.keyboard_variant")}"')
    if c("input.keyboard_options"):
        kb.append(f'    xkb_options "{c("input.keyboard_options")}"')
    scroll = float(c("input.scroll_factor"))
    out += [
        "",
        "input type:keyboard {",
        *kb,
        f"    repeat_delay {int(c('input.repeat_delay'))}",
        f"    repeat_rate {int(c('input.repeat_rate'))}",
        f"    xkb_numlock {'enabled' if c('input.numlock') else 'disabled'}",
        "}",
        "input type:touchpad {",
        f"    tap {'enabled' if c('input.touchpad_tap') else 'disabled'}",
        "    drag enabled",
        "    drag_lock disabled",
        f"    natural_scroll {'enabled' if c('input.natural_scroll') else 'disabled'}",
        "    dwt enabled",
        "    middle_emulation enabled",
        f"    pointer_accel {accel:g}",
        f"    scroll_factor {scroll:g}",
        "}",
        "input type:pointer {",
        "    accel_profile adaptive",
        f"    pointer_accel {accel:g}",
        f"    natural_scroll {'enabled' if c('input.mouse_natural_scroll') else 'disabled'}",
        f"    scroll_factor {scroll:g}",
        "}",
        "",
        "# dialogs, utilities and pop-ups float",
        'for_window [window_role="pop-up"] floating enable',
        'for_window [window_role="dialog"] floating enable',
        'for_window [window_type="dialog"] floating enable',
        'for_window [app_id="^(org.pulseaudio.pavucontrol|pavucontrol|blueman-manager|nm-connection-editor)$"] '
        "floating enable, resize set 760 520",
        'for_window [app_id="^org.surfd.(Settings|Welcome)$"] floating enable',
        'for_window [title="^Picture-in-Picture$"] floating enable, sticky enable',
        'for_window [app_id="^(swappy|system-config-printer|xdg-desktop-portal-gtk|lxpolkit)$"] floating enable',
        'for_window [title="^(Open|Save|Choose|Select) (File|Files|Folder|As|Image)"] floating enable',
        'for_window [app_id="^firefox$" title="^Library$"] floating enable',
        'for_window [class="^steam$" title="^(Friends List|Steam - News|Steam Settings)"] floating enable',
        'for_window [app_id="^surfd-monitor$"] floating enable, resize set width 70 ppt height 70 ppt, '
        "move position center",
        "# drop-down terminal (surfctl dropdown): lives in the scratchpad",
        'for_window [app_id="^surfd-dropdown$"] floating enable, border pixel 2, sticky enable, '
        "resize set width 90 ppt height 50 ppt, move position 5 ppt 0 ppt, move scratchpad, scratchpad show",
        "for_window [all] inhibit_idle fullscreen",
    ]
    if ctx.floating_mode:
        out += [
            "",
            "# mouse-friendly mode: every window floats with a title bar",
            "for_window [all] floating enable",
        ]

    out += ["", "# key bindings (from [keys.bindings])"]
    for b in keys.compile_bindings(ctx.cfg):
        flags = "--to-code" + (" --locked" if b.locked else "")
        out.append(f"bindsym {flags} {b.sway_combo} {b.command}")

    if c("osd.enabled"):
        osd = keys.osd_command({"step": c("osd.step"), "enabled": True})
        out += [
            "# Caps Lock and Num Lock show a flyout when released",
            f"bindsym --release --locked Caps_Lock exec {osd} capslock",
            f"bindsym --release --locked Num_Lock exec {osd} numlock",
        ]
    if c("display.clamshell"):
        out += [
            "# laptop lid: with another display connected, closing the lid turns the built-in screen off",
            f"bindswitch --reload --locked lid:on exec {LIBEXEC}/surfd-lid close",
            f"bindswitch --reload --locked lid:off exec {LIBEXEC}/surfd-lid open",
        ]

    out += [
        "",
        'mode "resize" {',
        "    bindsym Left resize shrink width 20px",
        "    bindsym Right resize grow width 20px",
        "    bindsym Up resize shrink height 20px",
        "    bindsym Down resize grow height 20px",
        "    bindsym h resize shrink width 20px",
        "    bindsym l resize grow width 20px",
        "    bindsym k resize shrink height 20px",
        "    bindsym j resize grow height 20px",
        '    bindsym Return mode "default"',
        '    bindsym Escape mode "default"',
        "}",
    ]

    if c("input.gestures"):
        out += [
            "",
            "# touchpad gestures",
            "bindgesture swipe:3:left workspace next_on_output",
            "bindgesture swipe:3:right workspace prev_on_output",
            f"bindgesture swipe:3:up exec {c('apps.launcher')}",
            "bindgesture swipe:4:up fullscreen toggle",
        ]

    lock = int(c("idle.lock_after"))
    off = int(c("idle.screen_off_after"))
    susp = int(c("idle.suspend_after"))
    waybar_cfg = ctx.gen / "waybar" / "config.jsonc"
    waybar_css = ctx.gen / "waybar" / "style.css"
    out += [
        "",
        "# session",
        "exec systemctl --user import-environment DISPLAY WAYLAND_DISPLAY SWAYSOCK "
        "XDG_CURRENT_DESKTOP XDG_SESSION_TYPE",
        "exec dbus-update-activation-environment --systemd DISPLAY WAYLAND_DISPLAY SWAYSOCK "
        "XDG_CURRENT_DESKTOP XDG_SESSION_TYPE",
        "exec systemctl --user start surfd-session.target",
        "exec lxpolkit",
        "exec mako",
        "exec_always makoctl reload",
        f'exec_always {LIBEXEC}/surfd-bar "{waybar_cfg}" "{waybar_css}"',
        f"exec_always {LIBEXEC}/surfd-idle {lock} {off} {susp}",
        f"exec_always {LIBEXEC}/surfd-dynwall {'on' if ctx.dynamic_follows_clock else 'off'}",
        f"exec_always makoctl mode -s {'do-not-disturb' if c('notifications.do_not_disturb') else 'default'}",
        # helpers that follow settings (each restarts itself, or stops when switched off)
        f"exec_always {LIBEXEC}/surfd-daemon autotile {'on' if c('layout.autotile') and not ctx.floating_mode else 'off'}",
        f"exec_always {LIBEXEC}/surfd-daemon clipboard {'on' if c('clipboard.history') else 'off'}",
        f"exec_always {LIBEXEC}/surfd-daemon power on",
        f"exec_always {LIBEXEC}/surfd-daemon nightlight {c('display.night_light')}",
        f"exec_always {LIBEXEC}/surfd-daemon updates {'on' if c('updates.check') else 'off'}",
        "exec udiskie --automount --notify --smart-tray",
        "exec surfctl apply --desktop-settings",
        "exec surfctl doctor --notify --quiet",
        "exec surfctl first-run",
    ]
    for cmd in c("autostart.commands"):
        if any(ch in cmd for ch in ";,\n"):
            continue  # validated elsewhere; never emit something Sway would split
        out.append(f"exec {cmd}")
    out += [
        "",
        "# system-wide and personal additions (last, so they can override)",
        "include /etc/surfd/sway.d/*.conf",
        f"include {paths.user_config_dir()}/sway.d/*.conf",
        "",
    ]
    return "\n".join(out)


