# ================================================================ terminal ==

def foot(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    t = [color.hex_no_hash(x) for x in p.terminal]
    lines = [_header("#", "terminal (foot)"), "[main]",
             f"font={c('fonts.mono')}:size={c('fonts.mono_size')}",
             "pad=14x12 center", "", "[cursor]", "style=beam", "blink=yes", "",
             "[mouse]", "hide-when-typing=yes", "", "[colors]",
             "alpha=0.97",
             f"foreground={color.hex_no_hash(p.text)}",
             f"background={color.hex_no_hash(p.background)}",
             f"selection-foreground={color.hex_no_hash(p.accent_text)}",
             f"selection-background={color.hex_no_hash(p.accent)}",
             f"urls={color.hex_no_hash(p.accent)}"]
    lines += [f"regular{i}={t[i]}" for i in range(8)]
    lines += [f"bright{i}={t[i + 8]}" for i in range(8)]
    return "\n".join(lines) + "\n"


# ============================================================= lock screen ==

def swaylock(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    h = color.hex_alpha
    lines = [_header("#", "lock screen (swaylock)"),
             f"font={c('fonts.ui')}",
             "indicator-radius=90",
             "indicator-thickness=7",
             "show-failed-attempts",
             "ignore-empty-password",
             f"color={color.hex_no_hash(p.background)}",
             f"inside-color={h(p.surface, 0.85)}",
             f"inside-clear-color={h(p.surface, 0.85)}",
             f"inside-ver-color={h(p.surface, 0.85)}",
             f"inside-wrong-color={h(p.surface, 0.85)}",
             f"ring-color={h(p.surface_alt, 1)}",
             f"ring-ver-color={h(p.accent, 1)}",
             f"ring-clear-color={h(p.warning, 1)}",
             f"ring-wrong-color={h(p.urgent, 1)}",
             f"key-hl-color={h(p.accent, 1)}",
             f"bs-hl-color={h(p.warning, 1)}",
             f"text-color={h(p.text, 1)}",
             f"text-ver-color={h(p.text, 1)}",
             f"text-wrong-color={h(p.urgent, 1)}",
             f"text-clear-color={h(p.text, 1)}",
             "line-color=00000000", "line-ver-color=00000000",
             "line-wrong-color=00000000", "line-clear-color=00000000",
             "separator-color=00000000"]
    wp = ctx.wallpaper
    if wp is not None and wp.suffix.lower() != ".svg":
        # While the wallpaper follows the clock the updater keeps this link on the current frame,
        # so the lock screen matches the desktop instead of the moment the config was written.
        lines += [f"image={dynwall.link_path() if ctx.dynamic_follows_clock else wp}", "scaling=fill"]
    return "\n".join(lines) + "\n"


# ===================================================================== GTK ==

def _gtk_named_colors(p: Palette) -> str:
    view_bg = color.mix(p.background, p.surface, 0.5)
    pairs = {
        "accent_color": p.accent if p.is_dark else color.mix(p.accent, "#000000", 0.15),
        "accent_bg_color": p.accent,
        "accent_fg_color": p.accent_text,
        "destructive_color": p.urgent,
        "destructive_bg_color": p.urgent,
        "destructive_fg_color": color.readable_on(p.urgent),
        "success_color": p.success,
        "warning_color": p.warning,
        "error_color": p.urgent,
        "window_bg_color": p.background,
        "window_fg_color": p.text,
        "view_bg_color": view_bg,
        "view_fg_color": p.text,
        "headerbar_bg_color": p.surface,
        "headerbar_fg_color": p.text,
        "headerbar_backdrop_color": p.background,
        "sidebar_bg_color": p.surface,
        "sidebar_fg_color": p.text,
        "card_bg_color": p.surface,
        "card_fg_color": p.text,
        "popover_bg_color": p.surface,
        "popover_fg_color": p.text,
        "dialog_bg_color": p.surface,
        "dialog_fg_color": p.text,
    }
    return "\n".join(f"@define-color {k} {v};" for k, v in pairs.items())


def gtk3_css(ctx: Context) -> str:
    extra = ctx.theme.extra("gtk.css")
    return (_header("/*", "GTK 3 colours").replace("\n/*", "\n *").rstrip("\n") + " */\n\n"
            + _gtk_named_colors(ctx.pal) + "\n" + (f"\n/* theme extras */\n{extra}" if extra else ""))


def gtk4_css(ctx: Context) -> str:
    p = ctx.pal
    variables = {
        "accent-color": p.accent if p.is_dark else color.mix(p.accent, "#000000", 0.15),
        "accent-bg-color": p.accent,
        "accent-fg-color": p.accent_text,
        "window-bg-color": p.background,
        "window-fg-color": p.text,
        "view-bg-color": color.mix(p.background, p.surface, 0.5),
        "view-fg-color": p.text,
        "headerbar-bg-color": p.surface,
        "headerbar-fg-color": p.text,
        "sidebar-bg-color": p.surface,
        "card-bg-color": p.surface,
        "popover-bg-color": p.surface,
        "dialog-bg-color": p.surface,
        "destructive-bg-color": p.urgent,
        "success-color": p.success,
        "warning-color": p.warning,
        "error-color": p.urgent,
    }
    root = ":root {\n" + "\n".join(f"  --{k}: {v};" for k, v in variables.items()) + "\n}\n"
    extra = ctx.theme.extra("gtk.css")
    # Named colours for libadwaita < 1.6, CSS variables for 1.6 and later.
    return (_header("/*", "GTK 4 / libadwaita colours").replace("\n/*", "\n *").rstrip("\n") + " */\n\n"
            + _gtk_named_colors(p) + "\n\n" + root + (f"\n/* theme extras */\n{extra}" if extra else ""))


def gtk_settings(ctx: Context, version: int) -> str:
    p, c = ctx.pal, ctx.c
    lines = [_header("#", f"GTK {version} settings"), "[Settings]"]
    if version == 3:
        lines.append(f"gtk-theme-name={'adw-gtk3-dark' if p.is_dark else 'adw-gtk3'}")
        lines.append(f"gtk-application-prefer-dark-theme={1 if p.is_dark else 0}")
    lines += [
        f"gtk-icon-theme-name={p.icon_theme}",
        f"gtk-cursor-theme-name={ctx.theme.cursor_theme}",
        f"gtk-cursor-theme-size={ctx.theme.cursor_size}",
        f"gtk-font-name={c('fonts.ui')} {c('fonts.size')}",
        "gtk-enable-animations=1",
        "gtk-decoration-layout=:close",
    ]
    return "\n".join(lines) + "\n"


# ====================================================================== Qt ==

def qt6ct_colors(ctx: Context) -> str:
    p = ctx.pal
    # QPalette roles, in qt6ct order (21 entries).
    def row(fg: str, bg: str, base: str, hl: str, hl_text: str) -> str:
        light = color.mix(bg, "#ffffff", 0.1)
        dark = color.mix(bg, "#000000", 0.3)
        mid = color.mix(bg, "#000000", 0.15)
        vals = [fg, bg, light, color.mix(bg, "#ffffff", 0.05), dark, mid, fg, "#ffffff", fg, base, bg,
                "#000000", hl, hl_text, p.accent, color.mix(p.accent, p.urgent, 0.4),
                color.mix(base, bg, 0.5), "#000000", p.surface, p.text, p.text_muted]
        return ", ".join("#ff" + color.hex_no_hash(v) for v in vals)

    base = color.mix(p.background, p.surface, 0.5)
    disabled_fg = color.mix(p.text, p.background, 0.55)
    return ("[ColorScheme]\n"
            f"active_colors={row(p.text, p.surface, base, p.accent, p.accent_text)}\n"
            f"disabled_colors={row(disabled_fg, p.surface, base, p.surface_alt, disabled_fg)}\n"
            f"inactive_colors={row(p.text, p.surface, base, p.surface_alt, p.text)}\n")


def qt6ct_conf(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    scheme = ctx.gen / "qt6ct" / "surfd-colors.conf"
    return (f"; {MARKER} from ~/.config/surfd/surfd.toml. Delete this line to take over.\n"
            "[Appearance]\n"
            f"color_scheme_path={scheme}\n"
            "custom_palette=true\n"
            f"icon_theme={p.icon_theme}\n"
            "standard_dialogs=xdgdesktopportal\n"
            "style=Fusion\n\n"
            "[Fonts]\n"
            f"fixed=\"{c('fonts.mono')},{c('fonts.mono_size')},-1,5,50,0,0,0,0,0\"\n"
            f"general=\"{c('fonts.ui')},{c('fonts.size')},-1,5,50,0,0,0,0,0\"\n")


