# ============================================================ write files ==

@dataclass
class Output:
    path: Path
    content: str
    managed: bool  # lives in an app's own config dir; respects marker takeover


def outputs(ctx: Context) -> list[Output]:
    gen = ctx.gen
    home = paths.config_home()
    return [
        Output(gen / "sway" / "config", sway(ctx), False),
        Output(gen / "waybar" / "config.jsonc", waybar_config(ctx), False),
        Output(gen / "waybar" / "style.css", waybar_css(ctx), False),
        Output(gen / "session.env", session_env(ctx), False),
        Output(gen / "qt6ct" / "surfd-colors.conf", qt6ct_colors(ctx), False),
        Output(gen / "osd.env", osd_env(ctx), False),
        Output(home / "xdg-desktop-portal" / "sway-portals.conf", portals_conf(ctx), True),
        Output(home / "xdg-desktop-portal-wlr" / "config", portal_wlr(ctx), True),
        Output(home / "swappy" / "config", swappy(ctx), True),
        Output(home / "mako" / "config", mako(ctx), True),
        Output(home / "fuzzel" / "fuzzel.ini", fuzzel(ctx), True),
        Output(home / "foot" / "foot.ini", foot(ctx), True),
        Output(home / "swaylock" / "config", swaylock(ctx), True),
        Output(home / "gtk-3.0" / "gtk.css", gtk3_css(ctx), True),
        Output(home / "gtk-3.0" / "settings.ini", gtk_settings(ctx, 3), True),
        Output(home / "gtk-4.0" / "gtk.css", gtk4_css(ctx), True),
        Output(home / "gtk-4.0" / "settings.ini", gtk_settings(ctx, 4), True),
        Output(home / "qt6ct" / "qt6ct.conf", qt6ct_conf(ctx), True),
    ]


def _is_ours(path: Path) -> bool:
    try:
        with path.open(encoding="utf-8", errors="replace") as fh:
            head = fh.read(400)
    except OSError:
        return False
    return MARKER in head


@dataclass
class WriteReport:
    written: list[Path]
    unchanged: list[Path]
    skipped: list[Path]  # user took the file over (no marker)


def write_all(ctx: Context, *, dry_run: bool = False) -> WriteReport:
    report = WriteReport([], [], [])
    if ctx.dynamic is not None and not dry_run:
        dynwall.update_link(ctx.dynamic[1])
    for out in outputs(ctx):
        if out.managed and out.path.exists() and not _is_ours(out.path):
            report.skipped.append(out.path)
            continue
        if out.path.exists() and out.path.read_text(encoding="utf-8", errors="replace") == out.content:
            report.unchanged.append(out.path)
            continue
        if not dry_run:
            config._atomic_write(out.path, out.content)
        report.written.append(out.path)
    return report
